function show(array $by, string $name, string $note): void {
    echo "\n== $note $name ==\n";
    if (!isset($by[$name])) { echo "ABSENT\n"; return; }
    $e = $by[$name];
    echo "pub={$e['publication']} since={$e['since']} kind={$e['kind']} final=".($e['final']?'1':'0')." enum=".($e['enum']??'-')."\n";
    echo "constants: ";
