    echo "\ncases: ";
    foreach ($e['cases'] ?? [] as $c) echo $c['name'].'='.json_encode($c['value']).'; ';
    echo "\nmethods: ";
    foreach ($e['methods'] as $m) echo $m['visibility'].' '.$m['name'].'(';
        $ps=[]; foreach ($m['parameters'] as $p) $ps[] = $p['name'].':'.$p['type'];
        echo implode(',', $ps).')';
        echo ($m['contracts']? ' C'.json_encode($m['contracts']):'');
        echo '; ';
    echo "\n";
