    foreach ($e['methods'] as $m) if ($m['visibility']==='protected') $prot[$n][]=$m['name'];
}
echo "\nclasses with protected methods: ".count($prot)."\n";
$i=0; foreach ($prot as $n=>$ms) { echo "  $n: ".implode(',', $ms)."\n"; if (++$i>=12) break; }

// final class should have no protected
$badFinal=[];
foreach ($by as $n=>$e) if ($e['final']) foreach ($e['methods'] as $m) if ($m['visibility']==='protected') $badFinal[]=$n.'::'.$m['name'];
echo "protected on final: ".json_encode($badFinal)."\n";

show($by, 'AzGuard\\Plugins\\PluginContext', 'internal ctor');
show($by, 'AzGuard\\Attributes\\SpiKind', 'enum');
show($by, 'AzGuard\\Changes\\ChangeStatus', 'enum closed');
show($by, 'AzGuard\\Events\\EventType', 'enum open');
show($by, 'AzGuard\\Facades\\AzGuard', 'facade class');

// a constant value check: find SCHEMA or similar
foreach ($by as $n=>$e) {
    foreach ($e['constants'] as $c) {
        if (in_array($c['name'], ['SCHEMA_VERSION','ALIAS','SYSTEM_TYPE'], true)) {
            echo "CONST $n::{$c['name']} = ".json_encode($c['value'])." vis={$c['visibility']}\n";
