<?php
require 'vendor/autoload.php';
require 'tests/Arch/SourceScan.php';
require 'tests/Arch/Ownership.php';
require 'tests/Arch/ApiUsage.php';
use AzGuard\Tests\Arch\ApiUsage;
use AzGuard\Tests\Arch\Ownership;
use AzGuard\Tests\Arch\SourceScan;

$root = getcwd().'/';
$own = Ownership::fromOracle();
$sup = ApiUsage::supported();
$hits = [];
foreach (ApiUsage::i4Files($own) as $file) {
    $code = (string) file_get_contents($file);
    $rel = str_replace($root,'',$file);
    $ns = SourceScan::namespace($code);
    $imports = SourceScan::imports($code);
    $resolve = function(string $name) use ($ns,$imports): string {
        if (str_starts_with($name,'\\')) return ltrim($name,'\\');
        [$first] = explode('\\',$name,2);
        if (isset($imports[strtolower($first)])) return $imports[strtolower($first)].substr($name, strlen($first));
        return ($ns===''?'':$ns.'\\').$name;
    };
    // Type|null $var or null|Type $var
    if (!preg_match_all('/(?:([A-Za-z_\\\\][A-Za-z0-9_\\\\]*)\|null|null\|([A-Za-z_\\\\][A-Za-z0-9_\\\\]*))\s+(\$[A-Za-z_][A-Za-z0-9_]*)/', $code, $m, PREG_SET_ORDER)) continue;
    foreach ($m as $hit) {
        $type = $hit[1] !== '' ? $hit[1] : $hit[2];
        $var = $hit[3];
        if (in_array(strtolower($type), ['string','int','array','bool','mixed','callable','iterable','object','false','true'], true)) continue;
        $fqcn = $resolve($type);
        $row = $own->typeRow($fqcn);
        if (($row['owner'] ?? null) !== 'core') continue;
        // find $var->method
        if (!preg_match_all('/\\'.preg_quote($var,'/').'->([A-Za-z_][A-Za-z0-9_]*)\s*\(/', $code, $calls)) continue;
        $entry = $sup[strtolower($fqcn)] ?? null;
        $names = $entry ? array_map('strtolower', array_column($entry['methods'],'name')) : [];
        foreach (array_unique($calls[1]) as $method) {
            $in = in_array(strtolower($method), $names, true);
            $hits[] = "$rel $fqcn $var->$method supported=".($entry?'yes':'NO')." listed=".($in?'yes':'NO');
        }
    }
}
echo "nullable-union member uses: ".count($hits)."\n";
foreach ($hits as $h) echo "  $h\n";
